{
  "findings": [
    {
      "check_id": "CKV_GCP_62",
      "title": "Cloud Function allows all users to invoke (missing IAM binding or explicit restriction)",
      "resource": "google_cloudfunctions_function.recovery_testing_service",
      "severity": "HIGH",
      "explanation": "The Cloud Function is triggered by a Pub/Sub topic. If the function's IAM policy allows 'allUsers' or 'allAuthenticatedUsers' to invoke it, or if the default permissions are overly permissive without explicit restrictions, it could be invoked by unauthorized actors. While the trigger itself requires Pub/Sub access, best practice dictates explicitly managing invocation permissions via `google_cloudfunctions_function_iam_member` or ensuring the function is not publicly accessible. However, a more direct and common misconfiguration in this context is the lack of encryption configuration for the source bucket or potential exposure via environment variables if they contained secrets (though here they are IPs/names). A critical missing security control often flagged in GCP Functions is the absence of `service_account_email`, which defaults to the App Engine service account with broad permissions, violating least privilege."
    },
    {
      "check_id": "CKV_GCP_63",
      "title": "Cloud Function does not specify a dedicated Service Account",
      "resource": "google_cloudfunctions_function.recovery_testing_service",
      "severity": "MEDIUM",
      "explanation": "The resource does not define a `service_account_email`. By default, Cloud Functions use the App Engine default service account, which often has excessive permissions (like Editor) on the project. This violates the principle of least privilege and increases the blast radius if the function is compromised."
    }
  ],
  "patched_code": "resource "google_cloudfunctions_function" "recovery_testing_service" {
  name        = "enterprise-disaster-recovery-orchestration-platform-function-testing"
  description = "Automated recovery testing service"
  runtime     = "python39"
  available_memory_mb   = 256
  source_archive_bucket = google_storage_bucket.primary_backup_storage.name
  source_archive_object = google_storage_bucket_object.testing_function_source.name
  trigger {
    event_type = "google.pubsub.topic.publish"
    resource   = google_pubsub_topic.recovery_testing_trigger.name
  }
  entry_point = "test_recovery"
  environment_variables = {
    DATABASE_HOST = google_sql_database_instance.recovery_database.ip_address.0.ip_address
    BACKUP_BUCKET = google_storage_bucket.primary_backup_storage.name
  }
  service_account_email = google_service_account.function_sa.email
  depends_on = [
    google_storage_bucket.primary_backup_storage,
    google_sql_database_instance.recovery_database,
    google_service_account.function_sa
  ]
}

resource "google_service_account" "function_sa" {
  account_id   = "recovery-test-func-sa"
  display_name = "Recovery Testing Function SA"
}",
  "fix_summary": "Added a dedicated Service Account (`google_service_account.function_sa`) and assigned it to the Cloud Function via `service_account_email` to enforce least privilege. Updated `depends_on` to include the new service account resource."
}
